entries[49636] = { ["name"] = "Zügel des Drachen von Onyxia", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachen von Onyxia oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sie hat viel mit ihrer Mutter gemein, nur dass diese getötet und wiedererweckt wurde. Doch sie ist ja noch jung. - Maloriak\"\nBeute von:\nOnyxia\nZone:\nOnyxias Hort" }
