entries[50250] = { ["name"] = "Herzbrecher X-45", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört eine reitbare Prototyprakete Herzbrecher X-45 oder gibt sie wieder frei. Diese Rakete passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Apotheker Hummel hat dieses Meisterwerk grell rosa angemalt, um seine unerwiderte Liebe widerzuspiegeln.\"\nBeute von:\nHerzförmige Schachtel\nFesttag:\nLiebe liegt in der Luft" }
